function requestAdmin(action){adminAuthAction=typeof action==="function"?action:null;var backdrop=document.getElementById("adminPasswordBackdrop"),input=document.getElementById("adminPasswordInput"),error=document.getElementById("adminPasswordError");input.value="";error.textContent="";backdrop.classList.remove("hidden");setTimeout(function(){input.focus()},0)}
function closeAdminPassword(){document.getElementById("adminPasswordBackdrop").classList.add("hidden");document.getElementById("adminPasswordInput").value="";document.getElementById("adminPasswordError").textContent="";adminAuthAction=null}
function submitAdminPassword(event){event.preventDefault();var input=document.getElementById("adminPasswordInput"),error=document.getElementById("adminPasswordError");if(input.value!=="admin"){error.textContent="Palavra-passe incorreta.";input.select();return}var action=adminAuthAction;document.getElementById("adminPasswordBackdrop").classList.add("hidden");input.value="";error.textContent="";adminAuthAction=null;if(action)action()}
function clearAdminResults(scope){requestAdmin(function(){clearAdminResultsConfirmed(scope)})}
function clearAdminResultsConfirmed(scope){if(!window.confirm("Limpar todos os resultados desta competição? Esta ação não pode ser anulada."))return;if(scope==="groups"){state.groupMatches.forEach(function(m){m.scoreA=null;m.scoreB=null});clearAllTieBreaks();state.knockout=null;state.doubleKo=null}else if(scope==="knockout"&&state.knockout){state.knockout.rounds.forEach(function(round){round.forEach(function(m){m.scoreA=null;m.scoreB=null;m.winner=null})});propagate()}else if(scope==="doubleko"&&state.doubleKo){state.doubleKo.upper.concat(state.doubleKo.lower).forEach(function(round){round.forEach(function(m){m.scoreA=null;m.scoreB=null;m.winner=null;m.loser=null;m.resolved=false})});state.doubleKo.finals.forEach(function(m){m.scoreA=null;m.scoreB=null;m.winner=null;m.loser=null;m.resolved=false});state.doubleKo.resetRequired=false;evaluateDoubleKo()}save();render()}
function generateAdminResults(scope){requestAdmin(function(){generateAdminResultsConfirmed(scope)})}
function generateAdminResultsConfirmed(scope){if(scope==="groups"){state.groupMatches.forEach(randomGroupTestScore);clearAllTieBreaks();state.knockout=null;state.doubleKo=null}else if(scope==="knockout"&&state.knockout){for(var guard=0;guard<500;guard++){propagate();var next=null;state.knockout.rounds.some(function(round){return round.some(function(m){if(m.a&&m.b&&m.scoreA==null){next=m;return true}return false})});if(!next)break;randomTestScore(next)}propagate()}else if(scope==="doubleko"&&state.doubleKo){for(var step=0;step<1000;step++){evaluateDoubleKo();var all=[];state.doubleKo.upper.forEach(function(round){all=all.concat(round)});state.doubleKo.lower.forEach(function(round){all=all.concat(round)});all.push(state.doubleKo.finals[0]);if(state.doubleKo.resetRequired)all.push(state.doubleKo.finals[1]);var pending=all.find(function(m){return m.a&&m.b&&!m.resolved});if(!pending)break;randomTestScore(pending)}evaluateDoubleKo()}save();render()}
function bindAdminTools(scope){document.querySelectorAll("[data-admin-clear='"+scope+"']").forEach(function(button){button.addEventListener("click",function(){clearAdminResults(scope)})});document.querySelectorAll("[data-admin-test='"+scope+"']").forEach(function(button){button.addEventListener("click",function(){generateAdminResults(scope)})})}
function tieBreakPanelsHtml(g,rows){var sets={};rows.forEach(function(row){if(row.tieBreakKey){if(!sets[row.tieBreakKey])sets[row.tieBreakKey]=[];sets[row.tieBreakKey].push(row)}});var automatic=Object.keys(sets).map(function(key){var tied=sets[key],resolved=tied.every(function(row){return !!row.tieBreakPosition}),names=tied.map(function(row){return row.name}),summary=resolved?"Ordem registada: "+names.join(" › "):names.join(", ");return"<div class='tie-break-card "+(resolved?"resolved":"pending")+"'><div><strong>⚖ DESEMPATE COLETIVO</strong><span>"+esc(summary)+"</span></div><button type='button' data-open-tiebreak='"+g+"' data-tie-key='"+esc(encodeURIComponent(key))+"'>"+(resolved?"ALTERAR ORDEM":"REGISTAR ORDEM")+"</button></div>"}).join(""),manual=rows.filter(function(row){return !!row.manualTieBreakPosition}).sort(function(a,b){return a.manualTieBreakPosition-b.manualTieBreakPosition});if(manual.length)automatic+="<div class='tie-break-card resolved manual'><div><strong>🛡 DESEMPATE MANUAL</strong><span>Ordem administrativa: "+esc(manual.map(function(row){return row.name}).join(" › "))+"</span></div><button type='button' data-open-manual-tiebreak='"+g+"'>ALTERAR ORDEM</button></div>";return automatic}
function unresolvedQualifyingTieGroups(){var blocked=[];state.groups.forEach(function(group,g){var rows=standings(g),cut=qualifierFor(g),sets={};rows.forEach(function(row,i){if(row.tieBreakPending&&row.tieBreakKey){if(!sets[row.tieBreakKey])sets[row.tieBreakKey]=[];sets[row.tieBreakKey].push(i)}});Object.keys(sets).some(function(key){var positions=sets[key],hasIn=positions.some(function(i){return i<cut}),hasOut=positions.some(function(i){return i>=cut});if(hasIn&&hasOut){blocked.push("Grupo "+letters[g]+" ("+(g+1)+")");return true}return false})});return blocked}
