function dkSeed(value){return{kind:"seed",value:value}}
function dkResult(section,round,index,outcome){return{kind:"result",section:section,round:round,index:index,outcome:outcome}}
function dkNewMatch(sourceA,sourceB){return{id:id(),sourceA:sourceA,sourceB:sourceB,a:null,b:null,scoreA:null,scoreB:null,winner:null,loser:null,resolved:false}}
function createDoubleKo(selected){var seeded=selected.slice(),size=1;while(size<seeded.length)size*=2;while(seeded.length<size)seeded.push(null);var upper=[],first=[];for(var i=0;i<size/2;i++)first.push(dkNewMatch(dkSeed(seeded[i]),dkSeed(seeded[size-1-i])));upper.push(first);var count=size/4;while(count>=1){var r=upper.length,round=[];for(var u=0;u<count;u++)round.push(dkNewMatch(dkResult("upper",r-1,u*2,"winner"),dkResult("upper",r-1,u*2+1,"winner")));upper.push(round);count=Math.floor(count/2)}var lower=[];if(size>=4){var lowerFirst=[];for(var l=0;l<size/4;l++)lowerFirst.push(dkNewMatch(dkResult("upper",0,l*2,"loser"),dkResult("upper",0,l*2+1,"loser")));lower.push(lowerFirst);for(var ur=1;ur<upper.length;ur++){var entry=[];for(var e=0;e<upper[ur].length;e++){var drop=e%2===0?e+1:e-1;if(drop>=upper[ur].length)drop=e;entry.push(dkNewMatch(dkResult("lower",lower.length-1,e,"winner"),dkResult("upper",ur,drop,"loser")))}lower.push(entry);if(ur<upper.length-1){var consolidation=[];for(var c=0;c<entry.length/2;c++)consolidation.push(dkNewMatch(dkResult("lower",lower.length-1,c*2,"winner"),dkResult("lower",lower.length-1,c*2+1,"winner")));lower.push(consolidation)}}}var upperFinal=dkResult("upper",upper.length-1,0,"winner"),lowerFinal=size===2?dkResult("upper",0,0,"loser"):dkResult("lower",lower.length-1,0,"winner"),grand=dkNewMatch(upperFinal,lowerFinal),reset=dkNewMatch(dkResult("finals",0,0,"winner"),dkResult("finals",0,0,"loser"));state.doubleKo={size:size,upper:upper,lower:lower,finals:[grand,reset],resetRequired:false,dropPattern:"crossed"};state.knockout=null;evaluateDoubleKo()}
